(function(){'use strict';let connection;
function db(){if(!connection)connection=new Promise((resolve,reject)=>{let r=indexedDB.open(globalThis.EngefexEnvironment?.storageKey('engefex-gerenciamento-files-v1')||'engefex-gerenciamento-files-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('files',{keyPath:'id'});r.onsuccess=()=>resolve(r.result);r.onerror=()=>{connection=null;reject(Error('Não foi possível abrir os anexos locais.'))}});return connection;}
async function transaction(mode,fn){let database=await db();return new Promise((resolve,reject)=>{let tx=database.transaction('files',mode),store=tx.objectStore('files'),result;fn(store,v=>result=v);tx.oncomplete=()=>resolve(result);tx.onerror=tx.onabort=()=>reject(Error('Não foi possível ler ou salvar anexos. Confira o espaço do aparelho.'))})}
async function load(ids){if(!ids.length)return [];return transaction('readonly',(s,set)=>{let values=new Array(ids.length);ids.forEach((id,i)=>{let r=s.get(id);r.onsuccess=()=>{values[i]=r.result;set(values)}})}).then(files=>{if(files.some(x=>!x))throw Error('Anexo ausente. Importe um backup que contenha os arquivos.');return files})}
const put=files=>files.length?transaction('readwrite',s=>{for(let f of files)s.put(f)}):Promise.resolve();
async function prepare(file,{optimizeImage=false}={}){if(file.size>20000000)throw Error('Limite por arquivo: 20 MB.');let dataURL,width,height;if(optimizeImage&&file.type.startsWith('image/')){let url=URL.createObjectURL(file),image=new Image();try{await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('Imagem incompatível. Use JPEG ou PNG.'));image.src=url});let scale=Math.min(1,1600/Math.max(image.naturalWidth,image.naturalHeight));width=Math.round(image.naturalWidth*scale);height=Math.round(image.naturalHeight*scale);let c=document.createElement('canvas');c.width=width;c.height=height;let ctx=c.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,width,height);ctx.drawImage(image,0,0,width,height);dataURL=c.toDataURL('image/jpeg',.86)}finally{URL.revokeObjectURL(url)}}else dataURL=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Falha ao ler anexo.'));r.readAsDataURL(file)});return {id:'FILE-'+(crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2)),name:file.name,type:width?'image/jpeg':file.type||'application/octet-stream',dataURL,width,height}}
function refs(state){let ids=new Set();function visit(x){if(!x||typeof x!=='object')return;if(Array.isArray(x)){for(let r of x)visit(r);return}for(let field of ['attachments','photos'])for(let f of x[field]||[])if(f.id)ids.add(f.id);for(let [key,value]of Object.entries(x))if(!['attachments','photos','photoFiles','fileFiles'].includes(key))visit(value)}visit(state);return [...ids]}

function catalog(state){let found=new Map(),labels={documents:'Documentos e projetos',receipts:'Recebimentos',purchases:'Compras e notas',laborContracts:'Medições de mão de obra',diary:'Diário de obras',projects:'Obras',measurements:'Medições'};function walk(value,context){if(!value||typeof value!=='object')return;if(Array.isArray(value)){for(let item of value)walk(item,context);return}let next={...context,project:value.project||context.project,record:value.name||value.title||value.description||value.number||context.record};for(let field of ['attachments','photos'])for(let meta of value[field]||[]){if(!meta?.id)continue;let file=found.get(meta.id);if(!file){file={...meta,name:meta.name||meta.id,sources:[]};found.set(meta.id,file)}file.sources.push({collection:context.collection,origin:labels[context.collection]||context.collection,project:next.project||'Geral',record:next.record||'Registro'})}for(let [key,item]of Object.entries(value))if(!['attachments','photos','photoFiles','fileFiles','dataURL'].includes(key))walk(item,next)}
for(let [collection,records]of Object.entries(state||{})){if(['history','photoFiles','fileFiles'].includes(collection)||!Array.isArray(records))continue;for(let record of records)walk(record,{collection,project:collection==='projects'?record.id:record.project,record:''})}return [...found.values()]}
function metadata(state,id){return catalog(state).find(f=>f.id===id)||catalog({historical:state?.history||[]}).find(f=>f.id===id)||null}
function blob(file){let match=String(file?.dataURL||'').match(/^data:([^;,]*)(?:;[^,]*)?;base64,([A-Za-z0-9+/=\s]*)$/);if(!match)throw Error('O arquivo não pôde ser lido. Tente carregá-lo novamente.');let decoded;try{decoded=atob(match[2])}catch{throw Error('O conteúdo do arquivo está inválido.')}return new Blob([Uint8Array.from(decoded,c=>c.charCodeAt(0))],{type:match[1]||file.type||'application/octet-stream'})}
async function download(input,meta={}){let file=typeof input==='string'?(await window.LocalFiles.load([input]))[0]:input;if(!file)throw Error('Arquivo não encontrado.');let content=blob(file),name=String(meta.name||file.name||file.id||'arquivo').replace(/[\/\\\x00-\x1f]/g,'_');if(content.type==='image/jpeg'&&/\.(png|heic|heif|webp)$/i.test(name))name=name.replace(/\.[^.]+$/,'.jpg');let url=URL.createObjectURL(content),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);try{a.click()}finally{a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}return {name,type:content.type,size:content.size}}
window.LocalFiles={load,put,prepare,refs,catalog,metadata,blob,download};})();

